package com.ventas.security;
import com.ventas.controller.RolePermissionController;import com.ventas.service.*;import com.ventas.security.AuthModels.Identity;import com.ventas.exception.ApiExceptionHandler;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(RolePermissionController.class) @ActiveProfiles("db") @Import({ApiSecurityConfig.class,SecurityConfig.class,ApiExceptionHandler.class}) class RolePermissionApiTest{
 @Autowired MockMvc mvc;@MockBean AuthService auth;@MockBean RolePermissionService service;void login(String...p){when(auth.authenticate(anyString(),anyString())).thenReturn(new Identity(1,"test","N","A","ADM",false,Set.of(p),UUID.randomUUID(),OffsetDateTime.now().plusHours(1)));}
 @Test void anonymousCannotReadRole()throws Exception{mvc.perform(get("/api/roles/2/permisos")).andExpect(status().isUnauthorized());}
 @Test void userAdministrationDoesNotGrantPermissionEditing()throws Exception{login("SEG.USUARIOS");mvc.perform(put("/api/roles/2/permisos").header("Authorization","Bearer test").contentType("application/json").content("{}")).andExpect(status().isForbidden());verifyNoInteractions(service);}
 @Test void missingVersionAndForgedFieldsAreRejected()throws Exception{login("SEG.PERMISOS");for(var body:List.of("{\"permisos\":[]}","{\"version\":\""+"a".repeat(64)+"\",\"permisos\":[],\"actor\":1}"))mvc.perform(put("/api/roles/2/permisos").header("Authorization","Bearer test").contentType("application/json").content(body)).andExpect(status().isBadRequest());verifyNoInteractions(service);}
 @Test void rolesCannotBeDeleted()throws Exception{login("SEG.PERMISOS");mvc.perform(delete("/api/roles/2").header("Authorization","Bearer test")).andExpect(status().isForbidden());}
}
